#!/usr/bin/env bash
# Regenerate committed replay bytes in a disposable checkout, preserving seals.
set -euo pipefail
# Every third-party module the scripts below import (tests check the list).
run() { uv run --with rfc8785==0.1.4 --with jsonschema --with numpy --with pyyaml python "$@"; }

# Check the original receipts before making the disposable namespaces writable.
run -m pipeline.uk_replay_qualify verify-sealed
git worktree add -q --detach "$RUNNER_TEMP/replay-regeneration" HEAD
cd "$RUNNER_TEMP/replay-regeneration"

seals=()
for root in results/uk/replays/*/; do
  [ -d "$root" ] || continue
  for name in REPLAY_RECEIPT.json NAMESPACE_MANIFEST.json; do
    path="$root$name"
    if [ -f "$path" ]; then
      seals+=("$path")
      rm "$path"
    fi
  done
done
restore_seals() {
  for path in "${seals[@]}"; do
    git show "HEAD:$path" > "$path"
  done
}
trap restore_seals EXIT

for root in results/uk/events results/uk/replays/*/; do
  [ -d "$root" ] || continue
  case "$root" in */diffs/) continue ;; esac
  found=0
  for manifest in "$root"/*/RUN_MANIFEST.json; do
    [ -f "$manifest" ] || continue
    found=1
    dir=$(dirname "$manifest")
    event=$(basename "$dir")
    run pipeline/stage_uk_event.py --event "$event" --artifact-dir "$dir" > /dev/null
    run pipeline/compare_uk_event.py --event "$event" --staged "$dir/STAGED.jsonl" --output-dir "$dir" > /dev/null
  done
  if [ "$found" = 1 ]; then
    run pipeline/compare_uk_event.py --summary --events-root "$root" > /dev/null
    echo "regenerated $root"
  fi
done
for diff in results/uk/replays/diffs/*/; do
  [ -f "$diff/DIFF.json" ] || continue
  base=$(run -c "import json,sys; print(json.load(open(sys.argv[1]))['base']['root'])" "$diff/DIFF.json")
  head=$(run -c "import json,sys; print(json.load(open(sys.argv[1]))['head']['root'])" "$diff/DIFF.json")
  run -m pipeline.diff_uk_event_runs --base "$base" --head "$head" --output-dir "$diff" --check
done

# Restore only the two seal files; keep regenerated bytes visible to the gate.
restore_seals
trap - EXIT
changes=$(git status --porcelain)
if [ -n "$changes" ]; then
  printf '%s\n' "$changes"
  echo "replay regeneration changed committed bytes or created untracked files" >&2
  exit 1
fi
